package main

const workbenchThemeCSS = `
:root{--ink:#242a2a;--muted:#69716e;--line:#dce0dc;--paper:#fff;--ground:#f3f4f0;--accent:#a8402d;--accent-soft:#f8eae4;--mono:ui-monospace,SFMono-Regular,Consolas,monospace}
[hidden]{display:none!important}body{font:14px/1.5 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink);background:var(--ground);padding:76px 28px 24px 224px;gap:20px}
button,input,select,textarea{font:inherit}button{touch-action:manipulation}.btn{font:500 13px/1.4 system-ui,sans-serif;border:1px solid var(--line);border-radius:6px;padding:7px 12px;background:#fff;color:var(--ink);transition:background .12s,border-color .12s}.btn:hover{background:#edf0ec;border-color:#a8b2aa}.btn:disabled{opacity:.45;cursor:default}.btn-run{background:var(--accent);border-color:var(--accent);color:#fff}.btn-run:hover{background:#8c3323;border-color:#8c3323}:focus-visible{outline:2px solid #287b75;outline-offset:3px}
input,select,textarea{border:1px solid #cbd2cb;border-radius:5px;background:white;color:var(--ink)}input,select{padding:8px}code,pre,kbd{font-family:var(--mono)}kbd{font-size:11px;color:var(--muted);border:1px solid var(--line);border-radius:4px;padding:3px 6px}
#hdr{position:fixed;inset:0 0 auto;height:56px;padding:0 28px;border-bottom:1px solid var(--line);gap:24px;z-index:2;flex-wrap:nowrap;background:#fff}#hdr h1{font-size:18px;font-weight:700;letter-spacing:-.6px;color:var(--ink);width:172px;flex-shrink:0}#hdr h1::after{content:'.';color:var(--accent)}#workbench-name{font-size:12px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}#connection-status{margin-left:auto;color:#43705c;font-size:12px;white-space:nowrap}#connection-status::before{content:'';display:inline-block;width:6px;height:6px;border-radius:50%;background:currentColor;margin-right:7px}#connection-status[data-offline=true]{color:var(--accent)}
#tool-rail{position:fixed;left:0;top:56px;bottom:0;width:196px;background:#fafbf8;border-right:1px solid var(--line);padding:24px 14px 18px;display:flex;flex-direction:column;gap:16px;overflow:auto}.rail-label,.eyebrow{font-size:10px;line-height:1.4;font-weight:650;letter-spacing:1.4px;text-transform:uppercase;color:var(--muted)}.rail-label{padding-left:12px}#workbench-tools{display:flex;flex-direction:column;gap:4px;flex:1}#workbench-tools .btn{text-align:left;background:transparent;border-color:transparent;padding:9px 12px;white-space:normal;overflow-wrap:anywhere}#workbench-tools .btn:hover{background:#e9ede6}#workbench-tools .btn[data-action=inspect]{background:var(--accent-soft);color:#863724}#workbench-status,#recording-status{font-size:12px;overflow-wrap:anywhere}.rail-config{border-top:1px solid var(--line);padding-top:16px}.rail-config .btn{width:100%;text-align:left}
.page-heading{display:flex;align-items:center;gap:16px;flex-shrink:0}.page-heading h2{font-size:26px;letter-spacing:-.8px;line-height:1.2;font-weight:600}.page-heading span{margin-left:auto;color:var(--muted);font-size:12px}#main{border:1px solid var(--line);border-radius:9px;background:white;min-height:210px;flex:1;box-shadow:0 2px 4px #24312704}#left{width:54%;min-width:0;border-color:var(--line)}.pane-heading{height:44px;flex-shrink:0;display:flex;justify-content:space-between;align-items:center;padding:0 20px;border-bottom:1px solid #eef0ec;color:var(--muted);font-size:12px}.pane-heading strong{font-weight:600;color:var(--ink)}#code{font:13px/1.9 var(--mono);padding:20px;min-height:130px;background:#fff;resize:none;border-radius:0}#bar{padding:12px 20px;border-top:1px solid #eef0ec;background:white;gap:10px}#hint{display:none}#right{min-width:0}#out{padding:20px;background:#fcfdfb}#out:empty::before{content:'Results appear here';color:#7a847b;font-size:13px}.ev{padding:0 0 16px;margin:0 0 16px;border:0;border-bottom:1px solid var(--line)}.ev-src{font:11px/1.7 var(--mono);color:var(--muted)}.ev-res,.ev-err{font:13px/1.8 var(--mono)}
#objs{height:208px;min-height:140px;background:white;border:1px solid var(--line);border-radius:9px;overflow:hidden}#objs-hdr{padding:12px 18px;gap:16px;align-items:center;background:white;font-size:13px;color:var(--ink);border-color:var(--line);flex-wrap:wrap}#objs-hdr strong{font-weight:600}#ocount{font-size:12px;color:var(--muted);margin-left:8px}#object-filter{margin-left:auto;min-width:110px;max-width:240px;padding:6px 9px;font-size:12px}#objs-hdr label{font-size:11px;color:var(--muted);display:flex;gap:6px;align-items:center}table{font-size:12px}th{background:#f7f8f5;color:var(--muted);padding:7px 18px;font-size:10px;text-transform:uppercase;letter-spacing:.8px}td{padding:8px 18px;border-color:#edf0eb}tr:hover td{background:#f6f8f3}.cn{color:var(--ink);font-weight:500}.oid{color:var(--muted);font:11px var(--mono)}.object-open{border:0;background:none;color:#3a7669;cursor:pointer;font:500 12px system-ui,sans-serif}
#mbg{background:#25342e4a;backdrop-filter:blur(3px)}#modal{width:min(960px,calc(100vw - 48px));max-height:90vh;padding:0;border:1px solid #d3dad2;border-radius:12px;box-shadow:0 20px 90px #1224192b}#inspect-header{padding:24px 28px 0;background:#fff;position:sticky;top:0;z-index:2;border-bottom:1px solid var(--line)}.inspect-heading{display:flex;align-items:flex-start;gap:20px;margin-bottom:22px}.inspect-heading>div{flex:1;min-width:0}#modal h3{color:var(--ink);font-size:25px;font-weight:600;letter-spacing:-.5px;margin:5px 0 0;word-break:normal;overflow-wrap:anywhere}#midentity{font:11px var(--mono);color:var(--muted);margin-top:4px;overflow-wrap:anywhere}#inspect-tabs{display:flex;gap:26px;overflow-x:auto}#inspect-tabs button{border:0;border-bottom:2px solid transparent;border-radius:0;background:none;padding:0 0 12px;color:var(--muted);white-space:nowrap}#inspect-tabs button[aria-selected=true]{border-color:var(--accent);color:var(--ink);font-weight:650}.inspect-pane{padding:26px 28px;min-height:260px}.inspect-pane h4{font-size:12px;color:var(--muted);font-weight:500;margin:20px 0 8px}#mproperties:empty,#mresult:empty{display:none}#mresult{margin:0 28px 24px;padding:14px;background:#f4f7f1;border-radius:6px;font-family:var(--mono)}.iv{padding:10px 0;font:12px/1.6 var(--mono);border-color:#eef0ec}.ivk{color:#38685c}.ivv{min-width:0}#mruntime{font:11px/1.8 var(--mono);color:var(--muted);padding:14px;background:#f7f8f5;border-radius:6px}details>summary{cursor:pointer;font-size:12px;color:var(--muted);padding:12px 0}#mactions{display:flex;gap:8px;flex-wrap:wrap;padding:8px 0}#mmths{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:7px;margin:12px 0 22px}#mmths button{margin:0;text-align:left;background:#f7f8f5;border:1px solid #e2e6df;border-radius:5px;padding:9px 11px;font:12px var(--mono);overflow-wrap:anywhere}#mmths button:hover{background:#e9eee6;border-color:#9daf9f}#method-filter{width:100%}#mcall{padding-top:18px;border-top:1px solid var(--line)}#mselector{margin:6px 0 10px;padding:10px!important;font-family:var(--mono)!important}#ow{border:0;padding:0;margin:0}#ow-target{font-size:12px;margin-bottom:14px}#ow-code{padding:16px;font:13px/1.8 var(--mono);min-height:180px}.objlink{font:12px var(--mono);color:#327369}
.view-tabs{margin-bottom:18px;gap:8px}.view-tabs:has(button:only-child){display:none}.view-tabs .btn{background:#f4f6f1}.view-tabs .btn[aria-pressed=true]{background:#e7eee2;border-color:#99ae95}.view-body{border:0;background:transparent;padding:0;margin:0}.view-tools{justify-content:flex-end;margin:0 0 20px}.view-tools>strong{margin-right:auto;font-size:16px;font-weight:600;align-self:center}.view-tools .btn{font-size:12px}.view-node{margin:0}.view-column{gap:18px}.view-row{gap:20px;align-items:stretch}.view-row>.view-column{flex:1 1 220px;border:1px solid var(--line);border-radius:8px;padding:24px;background:#fafbf8}.view-node>label{font-size:12px;font-weight:550;color:var(--muted);margin-bottom:8px}.view-value>span{font:500 48px/1.15 system-ui,sans-serif;letter-spacing:-2px;color:var(--ink)}.view-action>.btn{padding:9px 16px;background:var(--ink);color:white;border-color:var(--ink)}.view-action>.btn:hover{background:#3d4c44}.view-action>div:not(:empty){margin-top:10px;font-size:12px;overflow-wrap:anywhere}.view-input .marg,.view-slider .marg{margin:0;align-items:center}.view-input input{padding:9px 11px;font:14px var(--mono);width:0;min-width:60px}.view-textarea textarea{padding:10px;font-family:var(--mono)}.view-column>.view-action:last-child{padding-top:4px}.view-error{background:#fcf0eb;border-radius:6px;padding:10px}.view-code pre{font-size:12px;line-height:1.8}
.runtime-panel{border:1px solid var(--line);border-radius:10px;inset:24px;padding:24px;box-shadow:0 20px 90px #12241922}.runtime-toolbar{gap:10px;margin-bottom:20px}.runtime-toolbar>strong{font-size:20px;font-weight:600;letter-spacing:-.5px;margin-right:auto}.runtime-panel input,.runtime-panel select,.runtime-panel textarea{padding:8px}.runtime-status:empty{display:none}.runtime-status{font-size:12px}.visual-field{font-size:12px;color:var(--muted);gap:7px;margin:16px 0}.visual-field input,.visual-field select{color:var(--ink)}.visual-design-columns{grid-template-columns:minmax(140px,.8fr) minmax(0,2.5fr) minmax(210px,1fr);gap:24px}.visual-design-columns>section:nth-child(2){grid-column:3;grid-row:1}.visual-design-columns>section:last-child{grid-column:2;grid-row:1;background:#f4f6f1;padding:20px;border-radius:8px}.visual-design-columns h4{font-size:12px;font-weight:600}#view-design-preview{background:white;border-radius:6px;padding:16px}#view-design-preview .visual-preview-control{border-color:transparent;padding:6px}#view-design-preview .visual-preview-control:hover{border-color:#90a58b}#view-design-preview .visual-selected{outline-color:#46836f;background:#f4f9f0}#view-design-tree .btn{font-size:11px;padding-top:7px;padding-bottom:7px}#view-design-tree button[aria-pressed=true]{background:#e7eee2;border-color:#99ae95}
.starter-help{max-width:430px;color:var(--muted)}.starter-help strong{display:block;color:var(--ink);font-size:16px}.starter-help p{margin:6px 0 16px}.starter-help .btn{margin:0 6px 8px 0}.selector-help{display:flex;gap:8px;flex-wrap:wrap;align-items:center;color:var(--muted);font-size:12px;margin:0 0 10px}.selector-help:empty{display:none}.object-help{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:0 0 20px;color:var(--muted);font-size:12px}.object-help:empty,#mview-result:empty,.example-observed:empty{display:none}#mview-result,.example-observed{margin:18px 0 0;padding:14px;background:#f4f7f1;border-radius:6px;overflow-wrap:anywhere}.example-observed .btn{margin-left:12px}#examples-search{width:100%;margin-bottom:10px}#example-source{min-height:130px}#example-description{min-height:50px}#example-check{min-height:70px}#navigation{inset:24px;border-color:var(--line);border-radius:10px;overflow:hidden}#nav-toolbar{padding:16px;border-bottom:1px solid var(--line)}#nav-detail{padding:20px}#nav-graph,#wiring-graph{background:#f5f7f1}
#workbench-tools .btn[data-action=inspect]{background:transparent;color:var(--ink)}#workbench-tools .btn[data-action=inspect]:hover{background:#e9ede6}.ev-res{white-space:normal;word-break:normal}.result-value{margin:14px 0 18px;min-width:0}.result-type{font:600 10px/1.5 system-ui,sans-serif;color:var(--muted);letter-spacing:1px;text-transform:uppercase;margin-bottom:8px}.result-scalar{font:500 27px/1.4 var(--mono);overflow-wrap:anywhere}.result-text,.result-output{font:13px/1.7 var(--mono);white-space:pre-wrap;overflow-wrap:anywhere;word-break:normal;margin:0;max-width:100%;max-height:360px;overflow:auto}.result-output{padding-bottom:16px;border-bottom:1px solid var(--line)}.result-identity{font:10px var(--mono);color:var(--muted);margin-left:12px;overflow-wrap:anywhere}.result-inspect{font-size:14px;background:#eaf0e5;border-color:#bbcbb0}.result-actions{gap:8px;margin:10px 0;align-items:center;white-space:normal;font:12px/1.5 system-ui,sans-serif}.result-actions .btn{font-size:12px;padding:6px 10px}.result-more{font-family:system-ui,sans-serif}.result-more>summary{display:inline-block;padding:3px 0;color:#4a6c5a;font-size:12px}.result-more>summary::before{content:'+';margin-right:5px}.result-more[open]>summary::before{content:'-'}.result-more>.result-actions{padding:12px;background:#f0f3ed;border-radius:6px}.result-status{display:block;white-space:normal;color:var(--muted);font:12px/1.5 system-ui,sans-serif;margin-top:8px}.result-status:empty{display:none}.result-source{font:11px/1.7 var(--mono);color:var(--muted);white-space:pre-wrap;overflow-wrap:anywhere;max-height:72px;overflow:auto}.result-card{padding:20px 0}.result-empty{color:var(--muted)}#result-shelf,#recording-panel{border:1px solid var(--line);border-radius:10px;inset:24px;padding:24px;box-shadow:0 20px 90px #12241922}#result-shelf-list{max-width:900px}
#playground-starter{margin-left:auto;max-width:170px;min-width:0;padding:4px 7px;border-color:transparent;background:#f4f6f1;font-size:11px}.pane-heading{gap:10px}.result-collection{max-height:160px;overflow:auto;border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin:0 0 12px;font:12px/1.7 var(--mono)}.result-entry{display:grid;grid-template-columns:minmax(32px,auto) minmax(0,1fr);gap:12px;padding:5px 0;border-bottom:1px solid #eef0eb}.result-entry:last-child{border-bottom:0}.result-entry>div{white-space:pre-wrap;overflow-wrap:anywhere}.result-key{color:var(--muted);overflow-wrap:anywhere;max-width:120px}.result-collection-more{padding:8px;color:var(--muted);font:12px/1.5 system-ui,sans-serif}.view-value>span:not([data-kind=number]){display:block;font:14px/1.7 var(--mono);letter-spacing:0;white-space:pre-wrap;overflow-wrap:anywhere}.view-code pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto}
@media(max-width:1050px){body{padding-left:194px;padding-right:20px}#tool-rail{width:174px;padding-left:10px;padding-right:10px}#hdr h1{width:146px}.visual-design-columns{grid-template-columns:minmax(140px,1fr) minmax(0,2fr)}.visual-design-columns>section:nth-child(2){grid-column:1;grid-row:2}.visual-design-columns>section:last-child{grid-column:2;grid-row:1 / span 2}#objs-hdr{gap:8px}}
@media(max-width:650px){body{height:100dvh;padding:132px 12px 12px;gap:12px}#hdr{height:52px;padding:0 16px;gap:12px}#hdr h1{width:auto;font-size:17px}#workbench-name{display:none}#tool-rail{top:52px;bottom:auto;right:0;width:auto;height:64px;padding:10px 12px;display:flex;flex-direction:row;border-right:0;border-bottom:1px solid var(--line);gap:10px;overflow:auto}.rail-label,#workbench-status,#recording-status{display:none}#workbench-tools{flex-direction:row;gap:4px;flex:none}#workbench-tools .btn{white-space:nowrap;font-size:12px;padding:8px 10px}.rail-config{border:0;padding:0}.rail-config .btn{white-space:nowrap}.page-heading h2{font-size:22px}.page-heading span{display:none}#main{flex-direction:column;min-height:280px;overflow:auto}#left{width:100%;min-height:210px;flex:1;border-right:0;border-bottom:1px solid var(--line)}#right{min-height:125px;flex:1}.pane-heading{height:34px;padding:0 12px}#code{padding:12px;font-size:12px}#bar{padding:8px 12px}#hint{display:none}#out{padding:12px}#objs{height:180px}#objs-hdr{padding:10px 12px}#object-filter{max-width:none;width:100%;order:3}#objs-hdr label{margin-left:auto}th,td{padding:6px 12px}.oid{font-size:10px}#modal{width:calc(100vw - 20px);max-height:94dvh;border-radius:9px}#inspect-header{padding:18px 18px 0}.inspect-heading{margin-bottom:18px}#modal h3{font-size:22px}#inspect-tabs{gap:20px}#inspect-tabs button{font-size:12px}.inspect-pane{padding:18px;min-height:220px}.view-row>.view-column{padding:18px}.view-value>span{font-size:40px}#mresult{margin:0 18px 18px}#mmths{grid-template-columns:repeat(auto-fit,minmax(130px,1fr))}.runtime-panel,#navigation{inset:10px;padding:16px}.runtime-toolbar>strong{width:100%;font-size:20px}.visual-design-columns,.visual-columns{grid-template-columns:minmax(0,1fr)}.visual-design-columns>section:nth-child(2){grid-column:1;grid-row:3}.visual-design-columns>section:last-child{grid-column:1;grid-row:1}.visual-design-columns>section:first-child{grid-row:2}.view-tools{gap:6px}.view-tools>strong{flex-basis:100%;margin-bottom:6px}.view-tools .btn{padding:7px 9px}}
@media(max-width:650px){.pane-heading kbd{display:none}#result-shelf,#recording-panel{inset:10px;padding:16px}}
`
